61	      unit: "800 г - 1,1 кг",
62	    });
63	  });
64	
65	  test("Repeated product id keeps the first card", async () => {
66	    // The last record rec638793505 holds a card whose data-product-lid is again 1498486363994, titled
67	    // "Домашня сметана, 0,5 л" with price 270 — Tilda reuses lids across records.
68	    const fetchMock = fetchStub(200, fixtureHtml);
69	
70	    const products = productsOf(await createKarashynyardAdapter({ fetch: fetchMock }).fetchProducts());
71	
72	    const repeated = products.filter((p) => p.sourceId === "1498486363994");
